// publicapigen.go
package main

import (
	"bytes"
	"cmp"
	"context"
	"flag"
	"fmt"
	"go/ast"
	"go/parser"
	"go/printer"
	"go/token"
	"io"
	"os"
	"os/exec"
	"path"
	"path/filepath"
	"runtime"
	"sort"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/rs/zerolog"
	"github.com/rs/zerolog/log"
	"golang.org/x/tools/go/ast/astutil"
	"golang.org/x/tools/imports"
)

type registeredType struct {
	node ast.Expr
	docs *ast.CommentGroup
}

type registeredConstant struct {
	node ast.Expr
	typ  ast.Expr
	docs *ast.CommentGroup
}

type parsedFile struct {
	fileName string
	dir      string
	ast      *ast.File
}

var (
	// global state
	resolvedRepo        = "" // populated in main
	gitRef              = "" // populated in main
	fset                = token.NewFileSet()
	formattedFset       = token.NewFileSet()
	files               = []*parsedFile{}
	commentsToAddToFile = map[*ast.File]map[string]*ast.CommentGroup{}
	constants           = map[string]map[string]registeredConstant{}
	types               = map[string]map[string]registeredType{}
	typesToDrop         = map[string]map[string]bool{}
	usesPanicWrapper    = map[string]bool{} // package dir -> true

	// metrics
	totalParsedFiles    int32
	totalWrittenFiles   int32
	totalExportedTypes  int32
	totalExportedConsts int32
	totalExportedFuncs  int32
	totalDroppedTypes   int32
)

const panicWrapperSnippet = `
// doPanic is a wrapper around panic to prevent static analysis tools
// from thinking Encore APIs unconditionally panic.
func doPanic(v any) {
	if os.Getenv("ENCORERUNTIME_NOPANIC") == "" {
		panic(v)
	}
}
`

// Configuration flags
var (
	flagWorkers int
	flagOutDir  string
	flagDebug   bool
	flagRepoDir string
)

func init() {
	// default flags
	flag.IntVar(&flagWorkers, "workers", runtime.NumCPU(), "number of workers to parse files concurrently")
	flag.StringVar(&flagOutDir, "out", "", "output directory (default: computed from repo)")
	flag.BoolVar(&flagDebug, "debug", false, "enable debug logging")
	flag.StringVar(&flagRepoDir, "repo", "", "repo root directory (optional, auto-detected if empty)")
}

func main() {
	// Recover from any top-level panic so we can log it
	defer func() {
		if r := recover(); r != nil {
			fmt.Fprintf(os.Stderr, "fatal: recovered from panic: %v\n", r)
			os.Exit(2)
		}
	}()

	flag.Parse()
	// debug mode from flag or env
	if flagDebug || os.Getenv("ENCORE_DEBUG") == "1" {
		zerolog.SetGlobalLevel(zerolog.DebugLevel)
	} else {
		zerolog.SetGlobalLevel(zerolog.InfoLevel)
	}

	log.Logger = zerolog.New(zerolog.NewConsoleWriter()).With().Timestamp().Caller().Logger()

	log.Info().Msg("public API generator starting")

	// discover repo root and commit reference with retries
	var err error
	resolvedRepo, err = repoDirWithRetry(3, 500*time.Millisecond)
	if err != nil {
		log.Fatal().Err(err).Msg("unable to determine repo root")
	}
	gitRef, err = repoCommitWithRetry(3, 500*time.Millisecond)
	if err != nil {
		// not fatal — we can still continue, but log
		log.Warn().Err(err).Msg("unable to determine git ref (continuing without link to original sources)")
	}

	// default output dir if not set
	if flagOutDir == "" {
		flagOutDir = outDirFromRepo(resolvedRepo)
	}

	// clean global slices/maps
	files = files[:0]
	commentsToAddToFile = map[*ast.File]map[string]*ast.CommentGroup{}
	constants = map[string]map[string]registeredConstant{}
	types = map[string]map[string]registeredType{}
	typesToDrop = map[string]map[string]bool{}
	usesPanicWrapper = map[string]bool{}

	start := time.Now()

	// Walk and parse using a concurrent parser
	runtimePath := filepath.Join(resolvedRepo, "runtimes", "go")
	log.Info().Str("dir", runtimePath).Msg("parsing source files (concurrent)")

	if err := walkDirConcurrent(runtimePath, "./", readASTConcurrent); err != nil {
		log.Fatal().Err(err).Msg("walkDir failed")
	}

	// sort files for stable output
	sort.Slice(files, func(i, j int) bool {
		return cmp.Compare(files[i].fileName, files[j].fileName) < 0
	})
	log.Info().Int("files", len(files)).Msg("parsed source files")
	atomic.StoreInt32(&totalParsedFiles, int32(len(files)))

	// register types from private files and collect types-to-drop map
	log.Info().Msg("registering types from private implementation files")
	for _, f := range files {
		if isPrivateFile(f.fileName) {
			log.Debug().Str("file", f.fileName).Msg("registering types/constants from private")
			registerTypes(f.fileName, f.ast)
		}
		registerTypesToDrop(f.ast)
	}

	// rewrite ASTs to remove implementations and unexported items
	log.Info().Msg("rewriting ASTs to remove implementations and unexported items")
	var remaining []*parsedFile
	for _, f := range files {
		log.Debug().Str("file", f.fileName).Msg("rewriting ast")
		usesPanic, err := rewriteAST(f.ast)
		if err != nil {
			log.Fatal().Err(err).Str("file", f.fileName).Msg("unable to rewrite ast")
		}
		if len(f.ast.Decls) == 0 && f.ast.Doc == nil {
			log.Debug().Str("file", f.fileName).Msg("dropping file with no exported declarations")
			continue
		}
		if usesPanic {
			usesPanicWrapper[f.dir] = true
		}
		remaining = append(remaining, f)
	}
	files = remaining

	// write out files
	log.Info().Str("out", flagOutDir).Msg("writing public API files")
	if err := os.MkdirAll(flagOutDir, 0755); err != nil {
		log.Fatal().Err(err).Msg("unable to create output directory")
	}

	writtenPanicWrapper := make(map[string]bool) // package dir -> true
	for _, f := range files {
		if isPrivateFile(f.fileName) {
			// skip private files
			continue
		}
		log.Debug().Str("file", f.fileName).Msg("writing file")
		formattedFile := convertASTToFormattedSrc(fset, f.ast, f.fileName, nil)
		formattedAST, err := parser.ParseFile(formattedFset, f.fileName, formattedFile, parser.ParseComments)
		if err != nil {
			log.Fatal().Err(err).Str("file", f.fileName).Msg("unable to parse formatted file back into AST")
		}

		// attach pending comments like function doc markers and const docs
		writePendingComments(f.ast, formattedAST)

		// skip empty file after processing
		if isEmptyFile(formattedAST) {
			continue
		}

		var extraContents []byte
		doWritePanicWrapper := usesPanicWrapper[f.dir] && !writtenPanicWrapper[f.dir]
		if doWritePanicWrapper {
			extraContents = []byte(panicWrapperSnippet)
